const DEFAULT_PRECISION: i32 = 6;

pub fn format_cpp_floats(values: &[f32]) -> String {
    let mut parts = Vec::with_capacity(values.len());
    for &value in values {
        parts.push(format_cpp_float(value));
    }
    parts.join(" ")
}

pub fn format_cpp_float(value: f32) -> String {
    if value.is_nan() {
        return if value.is_sign_negative() {
            String::from("-nan")
        } else {
            String::from("nan")
        };
    }

    if value.is_infinite() {
        return if value.is_sign_negative() {
            String::from("-inf")
        } else {
            String::from("inf")
        };
    }

    if value == 0.0 {
        return if value.is_sign_negative() {
            String::from("-0")
        } else {
            String::from("0")
        };
    }

    let scientific = format!("{:.5e}", value);
    let (mut mantissa, exponent) = split_scientific(&scientific);

    if exponent < -4 || exponent >= DEFAULT_PRECISION {
        trim_fractional_zeros(&mut mantissa);
        return format!(
            "{}e{}{abs_exponent:02}",
            mantissa,
            if exponent < 0 { '-' } else { '+' },
            abs_exponent = exponent.abs()
        );
    }

    let digits_after_decimal = (DEFAULT_PRECISION - exponent - 1) as usize;
    let mut fixed = format!("{value:.digits_after_decimal$}");
    trim_fractional_zeros(&mut fixed);
    fixed
}

fn split_scientific(formatted: &str) -> (String, i32) {
    let (mantissa, exponent) = formatted
        .split_once('e')
        .expect("scientific formatting must contain an exponent");
    (
        mantissa.to_string(),
        exponent
            .parse::<i32>()
            .expect("scientific formatting must contain a valid exponent"),
    )
}

fn trim_fractional_zeros(value: &mut String) {
    if !value.contains('.') {
        return;
    }

    while value.ends_with('0') {
        value.pop();
    }

    if value.ends_with('.') {
        value.pop();
    }
}

