use super::{CMYK, HSL, HSV, RGB, YUV};

pub struct ColorConverter;

impl ColorConverter {
    pub fn rgb_to_hsl(rgb: RGB) -> HSL {
        let max = rgb.r.max(rgb.g).max(rgb.b);
        let min = rgb.r.min(rgb.g).min(rgb.b);
        let delta = max - min;
        let l = (max + min) / 2.0;

        if delta == 0.0 {
            return HSL { h: 0.0, s: 0.0, l };
        }

        let s = if l > 0.5 {
            delta / (2.0 - max - min)
        } else {
            delta / (max + min)
        };

        let mut h = if max == rgb.r {
            (rgb.g - rgb.b) / delta
        } else if max == rgb.g {
            ((rgb.b - rgb.r) / delta) + 2.0
        } else {
            ((rgb.r - rgb.g) / delta) + 4.0
        } * 60.0;

        if h < 0.0 {
            h += 360.0;
        }

        HSL { h, s, l }
    }

    pub fn rgb_to_hsv(rgb: RGB) -> HSV {
        let max = rgb.r.max(rgb.g).max(rgb.b);
        let min = rgb.r.min(rgb.g).min(rgb.b);
        let delta = max - min;
        let v = max;

        if delta == 0.0 {
            return HSV { h: 0.0, s: 0.0, v };
        }

        let s = if max == 0.0 { 0.0 } else { delta / max };

        let mut h = if max == rgb.r {
            (rgb.g - rgb.b) / delta
        } else if max == rgb.g {
            ((rgb.b - rgb.r) / delta) + 2.0
        } else {
            ((rgb.r - rgb.g) / delta) + 4.0
        } * 60.0;

        if h < 0.0 {
            h += 360.0;
        }

        HSV { h, s, v }
    }

    pub fn rgb_to_cmyk(rgb: RGB) -> CMYK {
        let k = 1.0 - rgb.r.max(rgb.g).max(rgb.b);

        if k == 1.0 {
            return CMYK {
                c: 0.0,
                m: 0.0,
                y: 0.0,
                k,
            };
        }

        let scale = 1.0 - k;
        CMYK {
            c: (1.0 - rgb.r - k) / scale,
            m: (1.0 - rgb.g - k) / scale,
            y: (1.0 - rgb.b - k) / scale,
            k,
        }
    }

    pub fn rgb_to_yuv(rgb: RGB) -> YUV {
        YUV {
            y: (0.299f32 * rgb.r) + (0.587f32 * rgb.g) + (0.114f32 * rgb.b),
            u: (-0.147f32 * rgb.r) + (-0.289f32 * rgb.g) + (0.436f32 * rgb.b),
            v: (0.615f32 * rgb.r) + (-0.515f32 * rgb.g) + (-0.1f32 * rgb.b),
        }
    }
}

